def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(obj):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return None

    def get_pos(obs, keys):
        for k in keys:
            p = pos(obs.get(k))
            if p is not None:
                return p
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_towards(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def best_by(items, score_fn, pick_min=True):
        best_item = None
        best_score = None
        for item in items:
            p = pos(item)
            if p is None:
                continue
            s = score_fn(p)
            if best_item is None or (pick_min and s < best_score) or ((not pick_min) and s > best_score):
                best_item = p
                best_score = s
        return best_item

