    sx_sy = get_pos(observation, ["self_position", "self", "agent_position", "position"])
    if sx_sy is None:
        return [0, 0]
    sx, sy = sx_sy

    ox_oy = get_pos(observation, ["opponent_position", "opponent", "enemy_position", "enemy"])
    width = observation.get("grid_width", observation.get("width", 0))
    height = observation.get("grid_height", observation.get("height", 0))

    if env == "pursuit_evasion":
