        if threat is None and ox_oy is not None:
            threat = ox_oy
        if threat is not None:
            move = step_away((sx, sy), threat)
        else:
            move = [0, 0]
        if width and height:
            corners = [(0, 0), (0, height - 1), (width - 1, 0), (width - 1, height - 1)]
            far_corner = max(corners, key=lambda c: manhattan(c, threat) if threat is not None else manhattan(c, (sx, sy)))
            corner_move = step_towards((sx, sy), far_corner)
            if abs(corner_move[0]) + abs(corner_move[1]) > abs(move[0]) + abs(move[1]):
                move = corner_move
        return move

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("neutral_cells")
            or observation.get("capture_cells")
            or observation.get("opponent_territory")
            or []
        )
        target = best_by(targets, lambda p: manhattan((sx, sy), p), True)
        if target is not None:
            return step_towards((sx, sy), target)
