    if ox_oy is not None:
        return step_towards((sx, sy), ox_oy)

    if width and height:
        center = (width // 2, height // 2)
        return step_towards((sx, sy), center)

    # Mild deterministic drift to avoid stagnation
    return [0, 1 if (sx + sy) % 2 == 0 else -1]

